// === ВАЛИДАЦИЯ (подготовка данных) + ГЕНЕРАЦИЯ submission_id ===
const item = $input.first();
const data = item.json;
const binary = item.binary;

// Чистые ключи из «красивых» лейблов формы
const submitter_name  = data['Name'];
const submitter_email = data['Email'];
const submission_type = data['Submission Type'];
const title           = data['Title'];
const comment         = data['Comment'] || '';

// Файл должен дойти — без него нечего маршрутизировать
const binaryKey = binary ? Object.keys(binary)[0] : undefined;
if (!binaryKey) {
  throw new Error('Validation failed: no file attached');
}
const fileBinary = binary[binaryKey];

// Генерируем submission_id
const date = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
let rand = '';
for (let i = 0; i < 8; i++) rand += chars[Math.floor(Math.random() * chars.length)];
const submission_id = `${date}-${rand}`;

return [{
  json: {
    submission_id,
    submitter_name,
    submitter_email,
    submission_type,
    title,
    comment,
    mime_type: fileBinary.mimeType,
    validated_at: new Date().toISOString()
  },
  binary: { file: fileBinary }
}];

